    Bug 1975127 - Get rid of `nsIHTMLEditor.rebuildDocumentFromSource()` in Thunderbird. r=masayuki

    Apparently (from tests) body is really *all* of the document, not just the body.

    Differential Revision: https://phabricator.services.mozilla.com/D255776

diff --git a/mail/components/compose/content/MsgComposeCommands.js b/mail/components/compose/content/MsgComposeCommands.js
index 9feaff0766e..ad56bc42d4b 100644
--- a/mail/components/compose/content/MsgComposeCommands.js
+++ b/mail/components/compose/content/MsgComposeCommands.js
@@ -6087,7 +6087,10 @@ function SetComposeDetails(newValues) {
     if (!IsHTMLEditor()) {
       throw Components.Exception("", Cr.NS_ERROR_UNEXPECTED);
     }
-    editor.rebuildDocumentFromSource(newValues.body);
+    // eslint-disable-next-line no-unsanitized/property
+    editor.document.documentElement.innerHTML = newValues.body;
+    editor.beginningOfDocument(); // Move caret to the first editable point.
+    editor.clearUndoRedo();
     gMsgCompose.bodyModified = true;
   }
